models.css:
.card {
    font-family: "Microsoft YaHei", "PingFang SC", "Hiragino Sans GB", sans-serif;
    text-align: center;
    color: #333;
    background-color: #fff;
    padding: 1.5em 1em;
}

.front-card,
.back-card {
    max-width: 620px;
    margin: 0 auto;
}

.front-card {
    min-height: 55vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.label {
    font-size: 16px;
    color: #888;
    margin-bottom: 0.15em;
}

.hanzi-front {
    font-size: 112px;
    line-height: 1.2;
    font-weight: 600;
    color: #2c3e50;
    margin: 0.15em 0 0.3em;
}

.components {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 1.4em;
}

.component {
    min-width: 110px;
}

.pinyin-part {
    font-size: 52px;
    line-height: 1.25;
    font-weight: bold;
    color: #2c3e50;
}

.audio-row {
    min-height: 32px;
    margin: 0.3em 0;
}

hr#answer {
    border: none;
    border-top: 2px solid #ddd;
    margin: 1.2em 0;
}

.combination-process {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 0.2em;
    margin: 0.2em 0 0.7em;
    font-size: 42px;
    line-height: 1.45;
    font-weight: bold;
}

.piece {
    color: #2c3e50;
}

.operator {
    color: #999;
    font-weight: normal;
}

.pinyin-result {
    color: #e74c3c;
}

.hanzi-result {
    color: #7b3fb2;
    font-size: 54px;
}

.complete-audio {
    margin-top: 0.5em;
}

.nightMode .card,
.night_mode .card {
    color: #eee;
    background-color: #222;
}

.nightMode .hanzi-front,
.nightMode .pinyin-part,
.nightMode .piece,
.night_mode .hanzi-front,
.night_mode .pinyin-part,
.night_mode .piece {
    color: #e5eef7;
}

@media (max-width: 480px) {
    .hanzi-front { font-size: 92px; }
    .pinyin-part { font-size: 44px; }
    .combination-process { font-size: 34px; }
    .hanzi-result { font-size: 46px; }
}
